// attract.js - the AI's winning area1 route, run-length encoded (generated by tools/rate-areas.mjs).
// Each item: first char = input bits (0-7), rest = run length in base 36.
export const ATTRACT_ROUTE = "22f,4a,21p,681,2o,41j,215,61s,23,626,2r,61h,2i,6w,03,4m,2l,62y,2x,64s,210,4k,23x,4g,06,4a,0c,4a,03l,63i,29k,6k,2l,6k,01q,24a,4k,24v,674,26m,4m,2f,6k,21s,66u";
export function decodeRoute(s) { const out = []; for (const r of s.split(",")) { const b = +r[0], n = parseInt(r.slice(1), 36); for (let i = 0; i < n; i++) out.push(b); } return Uint8Array.from(out); }
